insert into survey_consignor_efficiency_area_city(model_id, model_name, area_categories_id,area_categories_name, area_id, area_name,area_longname)
select #{modelId,jdbcType=BIGINT},#{modelName,jdbcType=VARCHAR},a.id,a.`name`,c.area_id,c.area_name,c.area_longname from survey_consignor_efficiency_model_area a
  left join survey_area_categories_area_city c on a.`name` = c.area_categories_name and c.price_model_id = #{selPriceModelId,jdbcType=BIGINT}
where a.model_id = #{modelId,jdbcType=BIGINT}
